contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 timeOffset) public payable {
        require(amount >= 10 ether, "need at least 10 ether to attempt the call");
        require(address(this).balance >= amount, "insufficient balance");

        // Use an external read-only call to observe initial state.
        // pastBlockTime() is the auto-generated getter for c's public variable.
        uint256 initialPastBlockTime = c.pastBlockTime();
        uint256 initialContractBalance = address(c).balance;

        // Choose a timestamp strictly greater than the current pastBlockTime.
        // We cannot easily read block.timestamp in the test without a call to a view helper,
        // so we use the current block timestamp plus an offset to be safely greater.
        uint256 attemptTimestamp = block.timestamp + timeOffset + 1;

        // The rule should verify that a failed call due to wrong value does not change the state.
        // Instead, we can assert that after a successful call with exactly 10 ether, the recorded
        // pastBlockTime equals the timestamp of that call and the balance only changes as expected.
        // However, we cannot control block.timestamp exactly. But we can observe the pastBlockTime after.

        // We will attempt the call with exactly 10 ether and observe outcomes.
        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 finalPastBlockTime = c.pastBlockTime();
        uint256 finalContractBalance = address(c).balance;

        // General rule: If the call did not revert, then pastBlockTime must have been updated
        // to the timestamp of the call (which is strictly greater than the previous one).
        // Also, the contract's balance change must be exactly +10 ether minus any transfer due to block.number % 15 == 0.
        // Since we cannot know block.number externally, the safest rule is that the balance after
        // is either initial+10 ether (no transfer) or 0 (if transfer happened).
        // Actually, if block.number % 15 == 0, the entire balance is transferred to msg.sender (the test contract).
        // So finalContractBalance would be 0. Otherwise, it would be initialContractBalance + 10 ether.
        // We can assert that finalContractBalance is either initialContractBalance + 10 ether or 0.
        // But note: msg.sender is the test contract, so the transfer would send ether back to the test contract.
        // That does not affect c's balance except by the required 10 ether.
        // However, if the transfer happens, c's balance becomes 0.
        // So the rule: finalContractBalance == initialContractBalance + 10 ether OR finalContractBalance == 0.
        // This must hold for any successful call.
        // Also, if the call did not revert, finalPastBlockTime must be greater than initialPastBlockTime.
        // But we cannot compare timestamps directly because we didn't record the call's block.timestamp.
        // We can at least assert that finalPastBlockTime >= block.timestamp (since the call happened now).
        // However, block.timestamp in the test might be slightly different from the call's timestamp if the call
        // occurs in the same transaction, but generally they should be the same block. So we assert
        // finalPastBlockTime == block.timestamp when not reverted.
        // This is a strong general rule: a successful call sets pastBlockTime to the current block timestamp.
        // Additionally, the balance rule holds.
        assert(
            reverted ||
            (finalPastBlockTime == block.timestamp &&
             (finalContractBalance == initialContractBalance + 10 ether || finalContractBalance == 0))
        );
    }

    receive() external payable {}
}

