contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 setupTime) public payable {
        // Ensure we have enough Ether for one fallback call plus possibly the balance sweep.
        require(address(this).balance >= 10 ether);

        // Advance pastBlockTime to a chosen future timestamp so that a subsequent call at a
        // higher block timestamp is guaranteed to satisfy `block.timestamp > pastBlockTime`.
        // We do this by making one setup call with 10 ether only if needed.  Since setupTime
        // is arbitrary, first read the current pastBlockTime and, if necessary, perform a setup
        // call at a timestamp we cannot control?  Instead we rely on the fact that any call
        // updates pastBlockTime to the current timestamp; we cannot set an arbitrary one.
        // The rule we test: after a successful call, the stored pastBlockTime equals the
        // block timestamp of that call.  We can observe that by making two calls in sequence:
        // the first call succeeds and sets pastBlockTime to T1; then a second call at the same
        // block would revert because block.timestamp is not strictly greater than T1.
        // However, a single transaction executes at one timestamp, so we cannot make two
        // calls at different timestamps in one test.  Therefore we focus on the immediate
        // effects of one call.

        uint beforeBalance = address(c).balance;
        uint beforePast = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // Successful call must have had block.timestamp > beforePast, and must have
            // updated pastBlockTime to the current block.timestamp.
            assert(c.pastBlockTime() == block.timestamp);
            // The call must have transferred exactly 10 ether from this contract to c,
            // or paid out the entire balance if block.number % 15 == 0.
            if (block.number % 15 == 0) {
                assert(address(this).balance == 10 ether + beforeBalance);
                assert(address(c).balance == 0);
            } else {
                assert(address(c).balance == beforeBalance + 10 ether);
            }
        } else {
            // A revert must be because the timestamp precondition failed.
            assert(block.timestamp <= beforePast);
            // State and balances remain unchanged after a reverted call.
            assert(c.pastBlockTime() == beforePast);
            assert(address(c).balance == beforeBalance);
        }
    }

    receive() external payable {}
}

