        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint timestampBefore;
        bool success;

        // Non-deterministically seed C with pastBlockTime == priorTimestamp if the
        // current pastBlockTime is 0 and priorTimestamp is less than the current
        // block timestamp.  This gives the fallback a chance to execute; otherwise
        // the timestamp requirement will make it revert.
        if (c.pastBlockTime() == 0 && priorTimestamp < block.timestamp) {
            (success, ) = address(c).call{value: amount}(abi.encodeWithSignature("fallback()"));
            if (success) {
                timestampBefore = block.timestamp;
            }
        }

        if (c.pastBlockTime() == 0) {
            (success, ) = address(c).call{value: amount}("");
            if (success) {
                timestampBefore = block.timestamp;
            }
        }

        uint balAfter = address(c).balance;

        if (success) {
            // Upon success the contract must record the current block timestamp.
            assert(c.pastBlockTime() == block.timestamp);

            // Ether can only increase by the exact amount sent, or drop to zero
            // (never partially decrease).
            assert(balAfter >= balBefore + amount || balAfter == 0);
        } else {
            // A failed call leaves the balance and stored timestamp unchanged.
            assert(balAfter == balBefore);
            assert(c.pastBlockTime() == 0);
        }
    }

    receive() external payable {}
}

