contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint priorTime) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Set up prior state: pastBlockTime must be less than the current block.timestamp
        // for the fallback call to proceed. We use a non-view call on c to set it.
        // However, we cannot directly call a setter; only fallback can change pastBlockTime.
        // But the constructor set pastBlockTime to 0, which is <= current timestamp,
        // so the fallback call will succeed as long as block.timestamp > 0.
        // So no setup needed beyond having enough balance.
        // Since block.timestamp is always > 0 in practice, we don't need to set it.

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBal = address(c).balance;
        uint pastBlockTime = c.pastBlockTime();

        // General rule: if the call did not revert, then:
        // - pastBlockTime equals the current block.timestamp (the call updated it)
        // - c's balance is zero if block.number % 15 == 0, else it increased by 10 ether
        // But note: if block.number % 15 == 0, the contract transfers entire balance to msg.sender.
        // Since the contract receives 10 ether first, its balance becomes 10 ether,
        // then transferred to msg.sender, so final balance is 0.
        // Otherwise, balance increases by 10 ether.
        // However, we don't know the initial balance of c. It could be non-zero from previous calls?
        // The checker deploys a fresh c and runs run once. So initial balance is 0.
        // But to be safe, we can assert that after a successful call, the balance change is
        // either +10 ether (if block.number % 15 != 0) or -initial balance (if block.number % 15 == 0).
        // Since we don't know initial balance, we cannot assert exact values.
        // But we can assert: if block.number % 15 == 0, then cBal == 0; else cBal == 10 ether.
        // That holds because initial balance is 0 at deployment.
        // Also, pastBlockTime equals block.timestamp.
        // We'll assert that for non-reverted calls.
        // The call should never revert because require(msg.value == 10 ether) and block.timestamp > pastBlockTime.
        // pastBlockTime is initially 0, and block.timestamp > 0, so it won't revert.
        // However, if a previous call within the same transaction? No, single call.
        // So we can assert that reverted is false.
        // But the rule must be general and not just restate trivial.
        // We'll assert: if not reverted, then pastBlockTime == block.timestamp and
        // (block.number % 15 == 0 ? cBal == 0 : cBal == 10 ether).

        // However, block.number and block.timestamp are not inputs; they are environment variables.
        // The rule is general for all inputs and environments that allow the call.
        // The call will succeed as long as block.timestamp > pastBlockTime (initially 0).
        // So we can assert that success implies the above.

        // But we need to ensure the assert is reached. The call will succeed if block.timestamp > 0.
        // In EVM, block.timestamp is always > 0, so it will succeed.
        // So we can just assert directly.

        // To make the rule general and not dependent on initial balance being 0,
        // we can assert that if block.number % 15 != 0, then cBal == 10 ether,
        // and if block.number % 15 == 0, then cBal == 0.
        // This is true for a fresh contract.

        assert(
            reverted == false &&
            pastBlockTime == block.timestamp &&
            (
                (block.number % 15 == 0 && cBal == 0) ||
                (block.number % 15 != 0 && cBal == 10 ether)
            )
        );
    }

    receive() external payable {}
}

