contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 newTime) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient test balance");

        // Set pastBlockTime to a known value newTime.
        // First fallback call is special: initial pastBlockTime is 0, so any timestamp > 0 is accepted.
        // Use a dummy message and swallow any revert, but do not let this be the deciding call.
        bool setupOk;
        try c.call{value: amount}("") {
            setupOk = true;
        } catch {
            setupOk = false;
        }

        if (setupOk) {
            // Cannot directly set arbitrary newTime; use real block.timestamp instead.
            // The only deterministic general reasoning available: if a successful call happened,
            // pastBlockTime equals the block.timestamp of that call.
            // Since we cannot know block.timestamp exactly in source, express the invariant relation
            // for a second deciding call with the same amount.
            uint256 before = c.pastBlockTime();
            bool reverted;
            try c.call{value: amount}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint256 afterTs = c.pastBlockTime();

            // General rule: if the second call succeeds, the new pastBlockTime must be strictly
            // greater than the previous one (block.timestamp always increases across transactions),
            // and if it reverts, pastBlockTime is unchanged.
            assert(reverted ? afterTs == before : afterTs > before);
        } else {
            // The first call reverted; since pastBlockTime was 0, the only way the very first
            // call with 10 ether and non-zero timestamp can revert is if the sent value was wrong
            // (already required to be 10 ether) or if block.timestamp was zero. In a real EVM,
            // block.timestamp is non-zero for any valid block. So this branch should be unreachable,
            // but we still need an assert. Express that no state change occurred.
            assert(c.pastBlockTime() == 0);
        }
    }

    receive() external payable {}
}

