            assert(amount != 10 ether || block.timestamp <= pastBefore);
            assert(balanceAfter == balanceBefore);
            assert(pastAfter == pastBefore);
        } else {
            assert(amount == 10 ether);
            assert(block.timestamp > pastBefore);
            assert(pastAfter == block.timestamp);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "amount must be exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTime = c.pastBlockTime();
        if (beforeTime != 0) {
            require(block.timestamp > beforeTime, "timestamp must exceed previous block time");
        }

        uint256 beforeBalance = address(c).balance;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.pastBlockTime() == block.timestamp && address(c).balance == beforeBalance + amount);
        } else {
            assert(c.pastBlockTime() == beforeTime);
        }
    }

    receive() external payable {}
}
